package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.gameevent.TickEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import dev.industrialtechnology.capacitor.*;import dev.industrialtechnology.client.*;import dev.industrialtechnology.core.*;
import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.inventory.GuiContainer;
import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.server.MinecraftServer;import net.minecraft.world.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import net.minecraft.init.Blocks;import net.minecraft.util.ScreenShotHelper;import org.lwjgl.opengl.GL11;
public final class BankClientChecks {
    private final List<String> report=Collections.synchronizedList(new ArrayList<String>());private int phase,wait=30,age;private boolean done;private volatile boolean ready,failed;private boolean realReference;
    public void init(){FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean b,String text){if(!b)throw new AssertionError(text);}
    private void pass(String text){report.add("PASS: "+text);IndustrialTechnology.log.info("BANK CLIENT PASS: "+text);}
    private static EntityPlayerMP player(){return (EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
    private static WorldServer world(){return (WorldServer)player().worldObj;}
    private void server(Runnable r){ServerWork.enqueue(()->{try{r.run();}catch(Throwable e){failed=true;report.add("FAIL: server :: "+e);IndustrialTechnology.log.error("Bank client server fixture",e);}});}
    private static TileCapacitorBank at(int x){return (TileCapacitorBank)world().getTileEntity(x,72,24);}
    private void fill(TileCapacitorBank b,long rf){ItemStack stack=new ItemStack(ModRegistry.capacitorBank);NBTTagCompound n=new NBTTagCompound();n.setInteger("BankVersion",1);n.setLong("StoredRF",rf);stack.setTagCompound(n);b.restoreItem(stack);}
    private static void shot(Minecraft mc,String name){ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
    private static int cyan(Minecraft mc,String name)throws Exception{java.awt.image.BufferedImage image=javax.imageio.ImageIO.read(new File(mc.mcDataDir,"screenshots/"+name));int count=0;for(int py=100;py<600;py++)for(int px=400;px<1200;px++){int c=image.getRGB(px,py),r=(c>>16)&255,g=(c>>8)&255,b=c&255;if(g-r>40&&b-r>40&&g>100)count++;}return count;}
    private static void click(GuiCapacitorBank gui,int id)throws Exception{Field f=GuiScreen.class.getDeclaredField("buttonList");f.setAccessible(true);Method m=GuiCapacitorBank.class.getDeclaredMethod("actionPerformed",GuiButton.class);m.setAccessible(true);for(Object o:(List)f.get(gui))if(((GuiButton)o).id==id){m.invoke(gui,o);return;}throw new AssertionError("button "+id);}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{
        if(failed){finish();return;}
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=3;mc.gameSettings.renderDistanceChunks=3;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(27,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT);s.func_82750_a("2;7;1;");mc.launchIntegratedServer("capacitor-client","Disposable capacitor visual QA",s);phase=1;wait=70;return;}
        if(mc.thePlayer==null||mc.theWorld==null){if(++age>100)throw new AssertionError("Join timeout");wait=10;return;}
        if(phase==1){mc.displayGuiScreen(null);TooltipClientChecks.prepare(mc);server(()->{WorldServer w=world();for(int x=20;x<40;x++)for(int z=20;z<36;z++)w.setBlock(x,71,z,Blocks.stone,0,3);w.setBlock(24,72,24,ModRegistry.capacitorBank,3,3);w.setBlock(25,72,24,ModRegistry.capacitorBank,3,3);fill(at(24),7500000);fill(at(25),15000000);
            net.minecraft.block.Block reference=ModRegistry.capacitorBank;
            if(cpw.mods.fml.common.Loader.isModLoaded("EnderIO")){try{reference=(net.minecraft.block.Block)Class.forName("crazypants.enderio.EnderIO").getField("blockCapBank").get(null);realReference=true;}catch(Exception ex){throw new RuntimeException(ex);}}
            for(int x=0;x<3;x++)for(int y=0;y<3;y++){w.setBlock(30+x,72+y,24,reference,3,3);if(reference==ModRegistry.capacitorBank)fill((TileCapacitorBank)w.getTileEntity(30+x,72+y,24),18750000);}
            player().playerNetServerHandler.setPlayerLocation(28,75,34,180,15);ready=true;});phase=2;wait=60;return;}
        if(phase==2){if(!ready){wait=10;return;}TileCapacitorBank b=(TileCapacitorBank)mc.theWorld.getTileEntity(24,72,24);
            for(int side=0;side<6;side++){String icon=ModRegistry.capacitorBank.getIcon(mc.theWorld,24,72,24,side).getIconName();check(icon.contains("capacitor/")&&!icon.contains("missing"),"missing face "+side);check(!b.showsGauge(side),"default gauge enabled");}
            check(GL11.glGetError()==GL11.GL_NO_ERROR,"world GL error");shot(mc,"capacitor-world-wall.png");check(cyan(mc,"capacitor-world-wall.png")<40,"default casing still has display overlay");pass("Default bank casing has no forced meter on any face or in the world framebuffer");pass("Client renders six original casing faces and clean connected borders");
            if(realReference)pass("Corrected normal casing renders beside actual unconfigured Ender IO Vibrant banks");
            server(()->{EntityPlayerMP p=player();p.setSneaking(true);p.inventory.mainInventory[p.inventory.currentItem]=null;check(p.theItemInWorldManager.activateBlockOrUseItem(p,world(),null,24,72,24,3,.5F,.5F,1),"shift activation");p.setSneaking(false);check(at(24).showsGauge(3)&&!at(25).showsGauge(3)&&at(24).network().ledger.stored()==22500000,"toggle changed other bank or energy");});phase=9;wait=30;return;}
        if(phase==9){TileCapacitorBank b=(TileCapacitorBank)mc.theWorld.getTileEntity(24,72,24);check(b.showsGauge(3)&&!b.showsGauge(2)&&b.displayCharge==8,"display packet not synchronized");shot(mc,"capacitor-optional-gauge.png");check(cyan(mc,"capacitor-optional-gauge.png")>20,"optional gauge not visibly lit");pass("Sneak plus empty-hand right-click enables one face's correctly cropped meter and synchronizes actual charge");
            server(()->{EntityPlayerMP p=player();p.setSneaking(true);check(p.theItemInWorldManager.activateBlockOrUseItem(p,world(),null,24,72,24,3,.5F,.5F,1),"toggle off activation");p.setSneaking(false);});phase=10;wait=25;return;}
        if(phase==10){check(!((TileCapacitorBank)mc.theWorld.getTileEntity(24,72,24)).showsGauge(3),"display did not turn off");shot(mc,"capacitor-casing-restored.png");pass("A second sneak-right-click restores the normal casing without changing stored RF");server(()->{EntityPlayerMP p=player();p.playerNetServerHandler.setPlayerLocation(24,72,27,180,0);check(p.theItemInWorldManager.activateBlockOrUseItem(p,world(),null,24,72,24,3,.5F,.5F,1),"GUI activation");});phase=3;wait=40;return;}
        if(phase==8){check(mc.currentScreen.getClass().getName().equals("codechicken.nei.recipe.GuiCraftingRecipe"),"Recipe screen closed");shot(mc,"capacitor-nei-recipe.png");pass("Actual NEI crafting screen finds and displays the capacitor survival recipe");finish();return;}
        check(mc.currentScreen instanceof GuiCapacitorBank,"Bank GUI unavailable in phase "+phase);GuiCapacitorBank gui=(GuiCapacitorBank)mc.currentScreen;
        if(phase==3){check(gui.state.getInteger("Banks")==2&&gui.state.getLong("Capacity")==50000000&&gui.state.getLong("Stored")==22500000,"snapshot stats "+gui.state);pass("Real open-GUI packet displays the complete shared 50M RF network and actual 45% charge");TooltipClientChecks.bank(mc,gui,this::pass);
            IndustrialTechnology.network.sendToServer(new BankCommand(gui.bankContainer.windowId,0,12345,0));IndustrialTechnology.network.sendToServer(new BankCommand(gui.bankContainer.windowId,1,21000,0));IndustrialTechnology.network.sendToServer(new BankCommand(gui.bankContainer.windowId,2,0,0));IndustrialTechnology.network.sendToServer(new BankCommand(gui.bankContainer.windowId,3,3,2));phase=4;wait=25;return;}
        if(phase==4){check(gui.state.getLong("LimitIn")==12345&&gui.state.getLong("LimitOut")==21000&&gui.state.getInteger("Redstone")==1&&!gui.state.getBoolean("Active")&&gui.state.getByteArray("Sides")[2]==3,"commands not authoritative");check(gui.state.getLong("Stored")==22500000,"settings changed RF");pass("Real client/server packets apply rate, redstone and face controls without changing stored RF");server(()->{check(at(24).network()==at(25).network(),"members not sharing");check(at(24).snapshot().getLong("Stored")==at(25).snapshot().getLong("Stored"),"member stats differ");});
            IndustrialTechnology.network.sendToServer(new BankCommand(gui.bankContainer.windowId+1,0,0,0));phase=5;wait=20;return;}
        if(phase==5){check(gui.state.getLong("LimitIn")==12345,"forged window changed settings");pass("Stale or forged window IDs cannot change capacitor settings");click(gui,11);TooltipClientChecks.bankSides(mc,gui,this::pass);click(gui,3);phase=6;wait=20;return;}
        if(phase==6){check(gui.state.getByteArray("Sides")[2]==0,"side button did not cycle disabled to input");pass("Side diagram mode button changes the selected face through a real server command");click(gui,10);IndustrialTechnology.network.sendToServer(new BankCommand(gui.bankContainer.windowId,0,Long.MAX_VALUE,0));phase=7;wait=20;return;}
        if(phase==7){check(gui.state.getLong("LimitIn")==50000,"unbounded input limit");pass("Server clamps a long-valued input limit to the physical multiblock maximum");check(GL11.glGetError()==GL11.GL_NO_ERROR,"GUI GL error");pass("Capacitor GUI and NEI finish with no OpenGL errors");
            Class<?> crafting=Class.forName("codechicken.nei.recipe.GuiCraftingRecipe");boolean opened=(Boolean)crafting.getMethod("openRecipeGui",String.class,Object[].class).invoke(null,"item",new Object[]{new ItemStack(ModRegistry.capacitorBank)});check(opened&&crafting.isInstance(mc.currentScreen),"NEI recipe unavailable");
            List handlers=(List)crafting.getMethod("getCurrentRecipeHandlers").invoke(mc.currentScreen);check(!handlers.isEmpty(),"No actual NEI crafting handler");Class<?> iface=Class.forName("codechicken.nei.recipe.IRecipeHandler");check((Integer)iface.getMethod("numRecipes").invoke(handlers.get(0))>0,"NEI handler empty");phase=8;wait=15;return;}
    }catch(Throwable ex){failed=true;report.add("FAIL: client phase "+phase+" :: "+ex);IndustrialTechnology.log.error("Capacitor client QA",ex);finish();}}
    private void finish(){if(done)return;done=true;try{report.add("Failed: "+(failed?1:0));Files.write(new File(Minecraft.getMinecraft().mcDataDir,"bank-client-report.txt").toPath(),report,StandardCharsets.UTF_8);}catch(Exception e){IndustrialTechnology.log.error("Bank report",e);}Minecraft.getMinecraft().shutdown();}
}
